import { html, renderToString } from '@cossackframework/renderer/server';

const name: string = '<script>alert(1)</script>';
const output: string = await renderToString(html`<p>Hello ${name}</p>`);
if (output.includes('<script>')) throw new Error('Text became executable markup');
if (!output.includes('&lt;script&gt;')) throw new Error('Text was not escaped');

import { choose, ifDefined, nothing, when } from '@cossackframework/renderer';
import { html, renderToString } from '@cossackframework/renderer/server';

const status: string = 'ready';
const output = await renderToString(html`<main><a href="${ifDefined(undefined)}">Home</a>${when(status !== 'hidden', () => html`<p>${choose(status, [['ready', () => 'Ready'], ['saving', () => 'Saving']], () => nothing)}</p>`, () => nothing)}</main>`);
if (output !== '<main><a>Home</a><p>Ready</p></main>') throw new Error(`Unexpected conditional output: ${output}`);

import { join, repeat } from '@cossackframework/renderer';
import { html, renderToString } from '@cossackframework/renderer/server';

const people = [{ id: 'ada', name: 'Ada' }, { id: 'lin', name: 'Lin' }];
const output = await renderToString(html`<ol>${repeat(people, person => person.id, person => html`<li data-id="${person.id}">${person.name}</li>`)}</ol><p>${join(people, person => person.name, ', ')}</p>`);
if (!output.includes('<li data-id="ada">Ada</li><li data-id="lin">Lin</li>')) throw new Error('Initial list order or values are wrong');
if (!output.endsWith('<p>Ada, Lin</p>')) throw new Error('List separator is missing');

import { bind, live } from '@cossackframework/renderer';
import { html, renderToString } from '@cossackframework/renderer/server';

const form = { email: 'agent@example.test', active: true, note: '<draft>' };
const output = await renderToString(html`<form><input name="email" .value=${bind(form, 'email')}><input name="active" type="checkbox" .checked=${bind(form, 'active')}><textarea name="note" .value=${live(form.note)}></textarea></form>`);
if (!output.includes('name="email" value="agent@example.test"')) throw new Error('Email value was not rendered');
if (!output.includes('type="checkbox" checked')) throw new Error('Checked state was not rendered');
if (!output.includes('&lt;draft&gt;</textarea>')) throw new Error('Textarea text was not escaped');

import { css, unsafeCSS } from '@cossackframework/renderer';

const gap = 8;
const surface = css`background-color: #fff;`;
const card = css`article { padding: ${gap}px; ${surface} }`;
if (!card.cssText.includes('padding: 8px')) throw new Error('Numeric CSS interpolation failed');
if (!card.cssText.includes('background-color: #fff')) throw new Error('CSSResult composition failed');
let rejected = false;
try { css`color: ${'red'};`; } catch { rejected = true; }
if (!rejected) throw new Error('A raw string was accepted by css');
const reviewedToken = unsafeCSS('var(--brand-color)');
if (!css`color: ${reviewedToken};`.cssText.includes('var(--brand-color)')) throw new Error('Reviewed CSS token did not compose');

import { CossackElement, component } from '@cossackframework/renderer';
import { html, renderToString } from '@cossackframework/renderer/server';

class Badge extends CossackElement {
  declare props: { tone?: 'info' | 'warning'; count?: number };
  render() {
    const { tone = 'info', count = 0 } = this.props;
    return html`<span class="badge ${tone}" data-count=${count}>${this.children}</span>`;
  }
}

class Alert extends Badge {}

const output = await renderToString(html`<p><${Badge} tone="warning" count=${3}>Late <b>2</b></${Badge}></p>`);
if (output !== '<p><span class="badge warning" data-count="3">Late <b>2</b></span></p>') throw new Error(`Unexpected tag output: ${output}`);

// component() remains for a class chosen at runtime.
const registry: Record<string, typeof Badge> = { badge: Badge, alert: Alert };
const chosen = await renderToString(html`<p>${component(registry['alert'], { count: 1 }, 'New')}</p>`);
if (chosen !== '<p><span class="badge info" data-count="1">New</span></p>') throw new Error(`Unexpected component() output: ${chosen}`);

import { parseTemplate } from '@cossackframework/renderer/template';

const strings = (template: TemplateStringsArray, ..._values: unknown[]) => [...template];
const parsed = parseTemplate(strings`<ul><li .title=${'x'}>${'Ada'}</li><div ${'dropped'}></div><input :value=${'v'}><div /></ul>`);
const codes: string[] = parsed.problems.map(problem => problem.code);
for (const code of ['COSSACK_TEMPLATE_DROPPED_BINDING', 'COSSACK_TEMPLATE_UNKNOWN_BINDING_PREFIX', 'COSSACK_TEMPLATE_SELF_CLOSING_ELEMENT']) {
  if (!codes.includes(code)) throw new Error(`Missing structural problem ${code}: ${codes.join(', ')}`);
}
if (parsed.bindings[1].kind !== 'node' || parsed.bindings[0].kind !== 'attribute') throw new Error('Binding roles are wrong');
